class PromptSection:
    """提示词片段。

    Attributes:
        priority: 优先级（越小越靠前）
        provider: 内容提供函数 (context) -> str
        name: 片段名称（用于日志/调试）
        condition: 条件函数 (context) -> bool（可选）
    """

    def __init__(self, priority: int, provider: Callable,
                 name: str = '', condition: Callable = None):
        self.priority = priority
        self.provider = provider
        self.name = name or provider.__name__
        self.condition = condition

    def should_include(self, context: Any) -> bool:
        """判断是否应包含此片段。"""
        if self.condition is None:
            return True
        try:
            return bool(self.condition(context))
        except Exception:
            logger.exception('提示词条件判断异常: %s', self.name)
            return False

    def render(self, context: Any) -> str:
        """渲染片段内容。"""
        try:
            return self.provider(context)
        except Exception:
            logger.exception('提示词片段渲染失败: %s', self.name)
            return ''


class PromptAssembler:
    """可插拔的系统提示词组装器。

    按优先级排序组装所有注册的提示词片段。
    支持条件片段（仅在特定条件下包含）。
    """

    def __init__(self, separator: str = '\n\n'):
        """
        Args:
            separator: 片段之间的分隔符
        """
        self._sections: list[PromptSection] = []
        self._separator = separator

    def register_section(self, priority: int, provider: Callable,
                         name: str = ''):
        """注册一个提示词片段。

        Args:
            priority: 优先级（越小越靠前）
            provider: 内容提供函数 (context) -> str
            name: 片段名称
        """
        self._sections.append(
            PromptSection(priority, provider, name))
        logger.debug('注册提示词片段: %s (priority=%d)',
                     name or provider.__name__, priority)

    def register_conditional(self, priority: int, provider: Callable,
                             condition: Callable, name: str = ''):
        """注册一个条件提示词片段。

        Args:
            priority: 优先级
            provider: 内容提供函数 (context) -> str
            condition: 条件函数 (context) -> bool
            name: 片段名称
        """
        self._sections.append(
            PromptSection(priority, provider, name, condition))
        logger.debug('注册条件提示词片段: %s (priority=%d)',
                     name or provider.__name__, priority)

    def remove_section(self, name: str):
        """移除指定名称的片段。"""
        self._sections = [s for s in self._sections if s.name != name]

    def assemble(self, context: Any = None) -> str:
        """组装完整的系统提示词。

        Args:
            context: 上下文对象（传递给各片段的 provider）

        Returns:
            组装后的完整提示词字符串
        """
        # 按优先级排序
        sorted_sections = sorted(self._sections, key=lambda s: s.priority)

        parts = []
        for section in sorted_sections:
            if not section.should_include(context):
                continue
            content = section.render(context)
            if content and content.strip():
                parts.append(content.strip())

        return self._separator.join(parts)

    def list_sections(self) -> list:
        """列出所有已注册的片段（用于调试）。"""
        return [
            {
                'name': s.name,
                'priority': s.priority,
                'conditional': s.condition is not None,
            }
            for s in sorted(self._sections, key=lambda s: s.priority)
        ]


