def make_base_identity(agent_id: str, home: str) -> Callable:
    """创建基础身份片段。"""
    def _provider(context):
        return (
            '你是数字员工 %s，隶属于公司的 AI 团队，运行在独立 Linux 工位上。\n'
            '你的家目录是 %s，所有文件操作必须限制在家目录内。\n'
            '回答使用中文，简洁专业。执行命令后请汇总结果给出人类可读的结论。\n'
            '重要：需要执行命令或读写文件时，直接按规范发起工具调用，'
            '严禁在回复正文里输出工具调用的 JSON 文本。'
        ) % (agent_id, home)
    return _provider


def make_tool_descriptions(tool_registry) -> Callable:
    """创建工具描述片段。"""
    def _provider(context):
        installed = tool_registry.installed_tools()
        if not installed:
            return '已安装的生产力工具：（尚未安装任何工具）'
        tool_lines = '\n'.join(
            '- %s (%s): %s' % (t.get('name'), t.get('key'),
                               t.get('description', ''))
            for t in installed)
        return '已安装的生产力工具：\n%s' % tool_lines
    return _provider


def make_skill_descriptions(skill_manager) -> Callable:
    """创建技能描述片段。"""
    def _provider(context):
        skills = skill_manager.list_skills()
        if not skills:
            return '已装备的技能：（无）'
        skill_lines = '\n'.join(
            '- %s: %s' % (s['name'], s['description'])
            for s in skills)
        return '已装备的技能：\n%s' % skill_lines
    return _provider


def make_metaskill_descriptions(metaskill_registry) -> Callable:
    """创建元技能描述片段。"""
    def _provider(context):
        metaskills = metaskill_registry.list_metaskills()
        if not metaskills:
            return ''
        lines = '\n'.join(
            '- %s: %s' % (m['name'], m['description'])
            for m in metaskills)
        return '可用的元技能（原子工具函数，无需 LLM）：\n%s' % lines
    return _provider


def make_rag_context(memory_manager) -> Callable:
    """创建 RAG 上下文片段（条件性）。"""
    def _provider(context):
        if not context or not hasattr(context, 'query'):
            return ''
        results = memory_manager.search_long_term(context.query, top_k=3)
        if not results:
            return ''
        rag_text = '\n'.join(
            r.get('text', '')[:200] for r in results if r.get('text'))
        return '[相关历史] %s' % rag_text if rag_text else ''

    def _condition(context):
        return context and hasattr(context, 'query') and context.query

    return _provider
